PHASE10_L2_REFERENCE_CASES_PART2 = [
    {
        "table": "reference_cases",
        "case_id": "REF_CASE:SIAC:Case_ARB_112_2020_Offshore_Wind_Vietnam:2021",
        "court": "Singapore International Arbitration Centre (新加坡国际仲裁中心 SIAC)",
        "senate": "Arbitral Tribunal (由三位国际新能源工程仲裁专家合议)",
        "decided": "2021-11-20",
        "az": "SIAC Case No. ARB 112/20/MC",
        "ecli": "ECLI:SIAC:ARB:2021:112",
        "doctype": "award",
        "leitsatz": "【SIAC新加坡仲裁院越南海上风电PPA补贴退坡与EPC情势变更调价裁决】：在越南重大海上风电特许开发 EPC 总承包争议中，SIAC 仲裁庭确立了有关新能源政策性电价（FIT）退坡与承包商合同风险分担的裁判标准：当越南工贸部因可再生能源补贴政策到期、出台第21/2023号决定将过渡期未并网光伏风电电价天花板大幅削减近30%、且仅先行按50%支付过渡电价时，该项主权政策突变属于签约时双方无法预见之重大外部情势变更（Hardship）；发包人企图将由此引发的全部数十亿越盾现金流损失通过单方全额扣除 EPC 承包款进行转嫁的行为严重违约，裁决发包人与总承包商公平分担损失，全额核发完工证书并支付拖欠设备工程款！",
        "tenor": "【SIAC国际仲裁庭终局裁决主文】：一、终审裁定仲裁申请人（中资新能源电力建设工程集团）在案涉越南平顺省100MW海上风电EPC总承包合同履约中，因新冠疫情口岸封锁与越方海事许可批复迟延导致未能赶上法定FIT补贴末班车，申请人已穷尽商业合理赶工努力，不构成主观恶意违约；二、确认越南工贸部 Decision 21/2023 出台的过渡期临时折价结算政策对案涉项目构成重大不可抗力级别情势变更；三、终局驳回被申请人（越南合资风电开发商）要求向申请人扣除高达18,200,000美元延误损失赔偿金的反诉请求；四、裁决被申请人必须于三十日内向申请人签发商业交工验收证书（PAC），并支付拖欠的最后一期大额机电设备供货与海缆铺设工程款共计21,500,000美元及SIAC法定商业利息；五、本案仲裁费用由被申请人负担75%，申请人负担25%。",
        "tatbestand": "【案件事实与各方主张陈述】：申请人某中资顶级可再生能源工程建设集团以 EPC 总承包交钥匙模式承建被申请人位于越南平顺省外海的100MW近海潮间带风力发电项目，合同总额逾1.8亿美元。合同专用条件明确载明：工程目标是确保在2021年10月31日越南法定海上风电优惠上网电价（FIT2，固定电价9.8美分/千瓦时）失效前实现商业并网运行（COD）。在施工过程中，因全球疫情突发、越南南部全面实行极其严苛的区域封锁隔离政策，加之越南海事局与国防部对敏感海域施工安全审查迟延达数月，导致深海大直径单桩沉桩与重型海上风机安装作业受阻。项目最终于2022年4月并网发电，比 FIT2 截止日推迟了半年。受此影响，越南电力公司（EVN）依据工贸部 Decision 21/2023 政策，仅同意按过渡电价最高限价的50%支付临时购电款，项目公司预期售电收入暴跌数千万美元。被申请人反向申请人发难，直接在最终结算中扣发全部未付工程款2,150万美元，并反索赔1,820万美元延误损失。申请人向 SIAC 提起新加坡仲裁。",
        "gruende": "【裁判理由阐述与司法论证逻辑】：SIAC 仲裁庭经审理后认为：一、关于越南法与国际商事法情势变更原则的适用。越南2015年民法典第420条及国际统一私法协会商事合同通则（UNIDROIT Principles）第6.2.2条均确立：履约期间因不可抗力客观原因发生不可预见的外部环境剧变，导致合同经济平衡发生根本性颠覆时，受损方享有衡平救济权。二、政策性 FIT 补贴截止日风险的法律分配。在案证据表明，发包人作为属地项目投资人，在签署 PPA 购电协议时，对其自身面临的政策补贴退坡风险享有最直接的商业利益，亦承担第一位的政策风险；发包人明知疫情封锁与政府海事审批迟延属于不可抗拒的外部行政障碍，却企图将整个电站商业模式崩塌的后果全部转嫁由施工承包商一人背负，明显违背了建设工程承揽中‘谁承担风险谁获得回报’的风险对等原则。三、总承包商完工权益必须得到保障。风电站已实际并网发电且源源不断产生绿色电力收益，总包商有权获得其合格工程的合同对价。四、【出海央企实操攻防启示】：中资央企出海东盟投资承包风电光伏等新能源 EPC 的‘FIT到期风暴’攻防经典判决！近三年来，越南、泰国、马来西亚等东盟国家的新能源上网电价补贴政策（FIT）频繁变脸甚至突击刹车，导致数百家中资总包面临‘项目没赶上旧补贴末班车，业主把亏损全赖在中资总包头上’的巨大法律风险！本案裁决为出海新能源央企打赢了极具标志性的一仗：在面对业主以‘未赶上 COD 补贴退坡’为由扣罚数千万美元工程款时，中资企业必须在 SIAC 仲裁中死死咬住两点——（1）固定政府审批迟延与疫情封锁不可抗力因果链条；（2）援引民法典第420条情势变更原则，将风险牢牢推回给投资方，彻底打掉业主的巨额反索赔！",
        "norms_meta": "VN:Decision_21_2023_MOIT;VN:Civil_Code_2015:Art420;INTL:FIDIC_2017:Cl20_2"
    },
    {
        "case_id": "REF_CASE:SIAC:Case_ARB_045_2018_Jakarta_LRT_Joint_Venture:2019",
        "court": "Singapore International Arbitration Centre (新加坡国际仲裁中心 SIAC)",
        "senate": "Arbitral Tribunal (由三位国际工程联合体争端仲裁员合议)",
        "decided": "2019-08-12",
        "az": "SIAC Case No. ARB 045/18/SZ",
        "ecli": "ECLI:SIAC:ARB:2019:045",
        "doctype": "award",
        "leitsatz": "【SIAC新加坡仲裁院印尼重大轨道交通KSO联合体内部违约追偿与独立税号清算裁决】：在跨国基础设施工程联合体（KSO / Joint Operation）内部纠纷仲裁中，SIAC 仲裁庭确立了具有高度实操指引的联营体合规管治法理：依据印尼2017年第2号《建筑服务法》第30条及第9/2022号税法条例，外国总承包商与印尼本土大型建筑企业组建的联合体（KSO），在民事与税务法律关系上具备独立准法人的核算地位；当印尼本土合作方严重违反联合体协议、擅自挪用联合体共管财务专户内的期中工程款、且怠于履行印尼建筑服务最终所得税（PPh Final 2.65%）代扣代缴合规法定义务时，构成对联合体内部合作协议的根本违约；中资联合体牵头方依法享有直接扣除其全部利润分配份额并要求其赔偿全部税务罚款损失之完全权利！",
        "tenor": "【SIAC国际仲裁庭终局裁决主文】：一、终审确认被申请人（印尼本土某大型国有持牌建筑股份公司）严重违反了双方订立之《雅加达轻轨（LRT）高架导轨标段联合运营体协议（KSO Agreement）》第8条及第14条；二、终审裁定申请人（某中资铁路工程建设集团出海子公司）作为 KSO 联合体牵头方（Lead Partner），有权依据联合体章程全面剥夺被申请人在后续工程段中的联合管理表决权及财务操作权；三、裁决被申请人必须于三十日内，向申请人全额返还其擅自截留挪用的发包人工程进度结算款共计12,400,000美元，并赔偿申请人因印尼国家税务局（DJP）下达税务追缴单所代垫的 PPh Final 最终税款及滞纳金共计4,850,000美元；四、本案全部仲裁规费及申请人开支律师费由被申请人全额负担。",
        "tatbestand": "【案件事实与各方主张陈述】：为满足印尼2017年第2号建筑法关于外资外国工程代表处（BUJKA）不得独立在印尼施工、必须与持有 Kualifikasi Besar（大型）资质的印尼本土承包商组建联合体（KSO）之强行法门槛，申请人某中资铁路央企与被申请人印尼某知名本土建筑上市公司签署《KSO联合体协议》，约定以 70%（中方）：30%（印尼方）的权益比例，共同承揽雅加达轻轨核心高架桥梁及铺轨工程。双方在印尼在岸银行开立了联合体独立税号（NPWP KSO）及双印签共管资金账户。工程进展顺利并持续收到雅加达省政府及发包人的期中款项。然而被申请人因其自身参与的其他外岛项目发生资金链断裂，竟利用其印尼本土主场便利，私自串通开户银行个别经理违规绕过中方U盾授权，擅自将共管账户内1,240万美元工程资金非法划转至其母公司账户用于偿还自身商业高利贷；更为恶劣的是，被申请人未将发包人代扣代缴的 PPh Final 完税凭证及时在税务局报税对账，导致印尼国税局直接向下达查封中方代表处在岸账户的税务行政令。中方作为联合体牵头人，依约向 SIAC 提起新加坡紧急仲裁维权。",
        "gruende": "【裁判理由阐述与司法论证逻辑】：SIAC 仲裁庭经审理后认为：一、KSO 联合体内部信义义务（Fiduciary Duty）之神圣性。KSO 联合体协议本质上属于国际商事伙伴之间的信托合伙关系，各方对联合体工程专款负有最高的信义保管法定义务；被申请人私自掏空共管账户资金填补自身漏洞的行为，不仅构成了严重的民事违约，更触犯了背信侵占商业道德底线。二、税法连带责任在联合体内部的最终责任追偿。依据印尼 PP 9/2022 条例，KSO 拥有独立税号时，虽然对外由联合体统一完税，但对内各方必须严格按照股权比例分摊税赋；因被申请人恶意抽逃资金导致中方为防止账户被封而垫付的485万美元税款及罚金，纯属被申请人违规侵权行为直接造成的实际财产损失，被申请人负有100%全额连带赔偿补偿义务。三、牵头方的单方除名接管权行使合法有效。仲裁庭完全支持中方将违约方从管理层清除以确保轻轨国家工程如期通车。四、【出海央企实操攻防启示】：中资央企出海在印尼组建 KSO 联合体‘防本地伙伴暗算掏空’的最高风控实操蓝本！在印尼承揽工程，法律强制要求中资企业必须找印尼本地企业组建 KSO，这是无法绕开的硬门槛。但很多中资企业‘前门防住了业主，后门却被自己的印尼 KSO 伙伴偷了家’！本案判决是中资企业在印尼搞 KSO 的保命指南：（1）共管账户绝不能图省事开在印尼不知名小银行，必须开在中资银行雅加达分行或印尼最大的外资持牌行，并严格设定‘中方财务一把手物理U盾+亲笔签字双重审批方可划款’；（2）在 KSO 协议中必须写死‘任何擅自动用资金直接构成根本违约、无条件丧失一切分红并由中方全面接管’；（3）争议条款坚决锁定新加坡 SIAC 仲裁，借用新加坡司法的铁面雷霆，彻底砸碎印尼本地伙伴在本土搞司法拖延的非分之想！",
        "norms_meta": "ID:UU_2_2017:Art30_KSO;ID:Tax_Law_KSO:PP_51_2008_jo_PP_9_2022;INTL:FIDIC_2017:Cl16_2"
    },
    {
        "case_id": "REF_CASE:SIAC:Case_ARB_310_2021_Bangkok_Condo_EPC:2022",
        "court": "Singapore International Arbitration Centre (新加坡国际仲裁中心 SIAC)",
        "senate": "Arbitral Tribunal (由三位国际商事仲裁员合议)",
        "decided": "2022-09-16",
        "az": "SIAC Case No. ARB 310/21/AA",
        "ecli": "ECLI:SIAC:ARB:2022:310",
        "doctype": "award",
        "leitsatz": "【SIAC新加坡仲裁院泰国大型EPC工程迟延利息新旧法适用与见索即付保函欺诈止付裁决】：在涉及泰国曼谷地标性商业综合体 EPC 总承包跨国仲裁中，SIAC 仲裁庭确立了有关泰国实体法修改与独立保函司法禁令的重大裁判指引：当合同准据法适用泰王国法时，关于未约定利率的金钱债务迟延履行利息，仲裁庭必须严格适用泰国2021年第2564号紧急法令修改后的《民商法典》第224条，裁决自2021年4月11日起统一按年利率5%计息，坚决驳回适用7.5%旧法高息的主张；同时，在审查发包人恶意索兑总承包商开立的数千万美元见索即付履约保函时，若有确凿证据证明发包人是在自身拒绝签发实质竣工证书、且明知自身未受实际损失的情形下进行报复性索兑，构成国际法上公认的‘恶意欺诈与不合良心索兑（Fraud and Unconscionability）’，仲裁庭依法签发紧急仲裁临时禁令，永久禁止发包人兑付保函！",
        "tenor": "【SIAC国际仲裁庭终局裁决主文】：一、确认仲裁申请人（中资大型建筑工程跨国公司）在案涉曼谷湄南河畔大型超高层商业公寓项目中承建之工程已达到实质竣工标准，被申请人（泰国著名房地产上市开发商）拒绝签发交工证书构成重大违约；二、终审裁定被申请人向担保银行发出全额没收申请人提交的24,000,000美元见索即付履约保函（Performance Bond）之索偿通知，构成严重的欺诈与极度不合良心索兑行为（Fraud and Manifest Unconscionability）；三、裁决签发终局永久禁令，严厉禁止被申请人以任何方式索兑或受领该笔2,400万美元保函款项，并判令被申请人立即向申请人退还保函原件；四、判令被申请人向申请人全额结清拖欠的工程进度尾款共计16,800,000美元，并依据泰国2021年修正后民商法典第224条按年利率5%加计违约利息；五、本案仲裁规费及申请人全额境外律师费由被申请人负担。",
        "tatbestand": "【案件事实与各方主张陈述】：申请人某中资建筑工程央企承建被申请人位于泰国曼谷核心区域的高达55层的超高层豪华公寓及大型购物中心综合体，合同额逾2.4亿美元，合同约定适用泰王国实体法，争议提交新加坡 SIAC 仲裁。申请人向被申请人提交了由某顶级外资银行曼谷分行出具的金额为2,400万美元的见索即付独立履约保函（受 URDG 758 惯例拘束）。工程于2021年初全面通过了曼谷市政建筑工程局的安全终验，绝大部分小业主已经进驻装修并取得钥匙。然而，被申请人因其自身商业地产招商不理想面临巨额现金流亏空，拒不向申请人签发正式移交验收证书（TOC），并借口存在极微小的地下车库局部地坪水渍，突然向担保银行提交索赔书，要求‘全额没收兑付整整2,400万美元的履约保函全款’以解其燃眉之急；同时在拖欠申请人的1,680万美元工程款上拒绝支付任何利息。申请人当即依据 SIAC 紧急仲裁员程序（Emergency Arbitrator）申请紧急临时禁令，指控发包人构成实质性恶意欺诈与不合良心索兑，并提请全面仲裁。",
        "gruende": "【裁判理由阐述与司法论证逻辑】：SIAC 仲裁庭经深入审理后认为：一、独立保函欺诈与不合良心例外（Unconscionability Exception）之确立。见索即付保函虽然具有独立于基础承揽合同的抽象性，但国际商事法及普通法普遍确立了‘欺诈与显失良心例外’：当受益人根本不享有任何善意的诚实权利主张基础、而将见索即付保函纯粹用作讹诈承包商现金流的恶意施压工具时，法庭与仲裁庭必须果断介入切断保函兑付，捍卫司法正义。二、案涉大楼已被实质接收并全面商用，未发生任何可证明的重大结构损害，发包人在全盘知晓上述事实的情况下企图卷走2,400万美元现金，属于赤裸裸的滥用保函权利。三、关于泰国实体法迟延利率新标准的严格适用。针对拖欠工程款的利息主张，仲裁庭审查了泰国2021年4月颁布的 Emergency Decree B.E. 2564 对民商法典第224条的法定修正，确认旧法7.5%利率在法律上已被永久废除，仲裁庭严格适用新法裁定按年化5%计收利息。四、【出海央企实操攻防启示】：中资央企出海遭遇海外业主‘恶意炸保函’的紧急仲裁阻击战法！在海外承包中，最惊心动魄的时刻莫过于‘大楼建好了，业主突然向银行偷袭兑付几千万美元保函’！这在中资企业身上屡见不鲜！本案揭示了出海工程企业打赢‘保函保卫战’的标准流水线：（1）保函千万不能签让东盟当地地方法院管辖的文本，必须写明由新加坡 SIAC 仲裁并适用 URDG 758；（2）一旦业主向银行递交索赔书，中资企业必须在银行审单的 5 个营业日倒计时内，以闪电速度向 SIAC 申请‘紧急仲裁员（Emergency Arbitrator）’；（3）迅速固定大楼已投入商用的事实证据，证明业主构成‘显失良心（Unconscionability）’，在48小时内拿下紧急仲裁员禁令甩在银行脸上，成功把几千万美元保函直接按死在柜台上！",
        "norms_meta": "TH:CCC:Sec224_2021;INTL:URDG_758:Art15;INTL:URDG_758:Art20"
    },
    {
        "case_id": "REF_CASE:SIAC:Case_ARB_205_2019_Manila_Water_PPP:2020",
        "court": "Singapore International Arbitration Centre (新加坡国际仲裁中心 SIAC)",
        "senate": "Arbitral Tribunal (由三位国际公用事业PPP特许权法仲裁员合议)",
        "decided": "2020-04-10",
        "az": "SIAC Case No. ARB 205/19/LO",
        "ecli": "ECLI:SIAC:ARB:2020:205",
        "doctype": "award",
        "leitsatz": "【SIAC新加坡仲裁院马尼拉水务PPP特许经营通胀水价调整与主权征收裁决】：在涉及菲律宾首都大都会区核心水务管网特许经营权（PPP/Concession Agreement）的国际商业仲裁中，SIAC 仲裁庭作出了轰动全球水务投资领域的里程碑裁决：当特许经营权协议明确设立了依据消费者物价指数及外汇通胀每五年进行一次‘特许基本费率客观重置机制（Standard Rate Rebasing）’时，菲律宾国家公用事业水务监管局（MWSS-RO）由于国内政治压力，单方发布行政命令强行将中资及国际投资人排除在合理的资本回报率之外、并强令全面下调法定供水费率的行政干预行为，构成对特许权协议商业核心平衡的根本破坏；裁决菲律宾主权监管机构必须向特许经营项目公司赔偿因人为压低水价遭受的全部数十亿比索实质利润损失！",
        "tenor": "【SIAC国际仲裁庭终局裁决主文】：一、终审确认仲裁申请人（马尼拉东区特许经营水务集团公司，包含中资战略投资联合体）依据1997年《特许经营权协议》第9条享有的法定费率重置与通胀水价调整权利合法有效；二、终审裁定被申请人（菲律宾大都会水务给排水总署 Metropolitan Waterworks and Sewerage System / MWSS）在第4次费率重置周期中单方行政下调水价并拒绝执行物价指数调整之行政指令，构成对特许合同核心条款的根本重大违约；三、裁决被申请人必须于六十日内，向申请人全额赔偿自违约之日起至裁决之日止由于水价被压制所遭受的净商业利润减损共计7,420,000,000菲律宾比索（约合近1.5亿美元）；四、确认申请人有权在后续计费周期中依法恢复适用依合同公式计算之合法通胀水价；五、本案仲裁费用由被申请人全额负担。",
        "tatbestand": "【案件事实与各方主张陈述】：申请人某国际知名水务投资联合体（包含某中资大型水务环境水务集团出海合资实体）于1997年世界银行主导的公用事业私有化中，成功赢得为期长达25年的菲律宾马尼拉东区大都会供水与污水处理独家特许经营权合同（特许人口超600万）。协议明确确立了确保投资者获得市场公允加权平均资本成本（WACC，通常核定为9.3%）的‘每五年一次费率客观重置评估机制（Rate Rebasing）’。多年来项目公司斥巨资改造了破旧的供水管网，漏损率从63%大幅下降至11%。然而在2015年开启的新一轮重置周期中，恰逢菲律宾大选，民粹政客掀起‘反对水务外资暴利’的抗议浪潮。菲律宾政府水务监管局（MWSS）屈从于政治压力，突然单方修改计算规则，不仅不批准依据通胀上调水价，反而强行动用行政命令要求项目公司将基础水价单方下调每立方米近3比索，并强令禁止将企业所得税支出计入供水成本。项目公司每年数十亿比索现金流遭受严重侵蚀、项目贷款偿还发生严重困难。项目公司依特许合同仲裁条款将争议提请新加坡 SIAC 国际仲裁维权。",
        "gruende": "【裁判理由阐述与司法论证逻辑】：SIAC 仲裁庭经深入财务法务穿透审计后一致认为：一、公共特许经营权（PPP/BOT）契约精神的至高地位。公用事业特许经营合同由于周期漫长（25年至30年）、前期资本性开支极其庞大，外国投资者能够持续投入巨资的前提，完全取决于东道国政府承诺的费率动态重置与公允回报率公式的不可动摇性；东道国一旦出于短期政治讨好选民的目的擅自随意践踏既定规则，现代特许经营机制的法治基石将荡然无存。二、监管局违规干预的实质甄别。MWSS 所谓‘公用事业不能将公司所得税列为运营成本’的抗辩，完全违背了特许协议第9条的历史真实缔约意图和长达15年的既定连续履约惯例；监管局在没有法定上位法依据的情形下单方推翻经专业核算的价格指数，构成了严重的合同违约与行政专断。三、完全损害赔偿原则（Full Reparation）之贯彻。裁决赔偿金额严格基于独立的国际特许经营财务模型对实际现金流减损的精确量化计算，必须让投资者恢复到合同未被侵害时的完全财务状态。四、【出海央企实操攻防启示】：中资央企在东盟投资公用事业（水务、固废垃圾焚烧、燃气特许经营）应对政府强行压价的‘以打促谈’最高胜诉典范！很多央企在海外做 PPP 项目，最怕的就是当地政府或者监管局仗着‘公共利益大旗’和‘选民情绪’，强行发公文要求中资降价、赖掉调价公式！本案向所有出海企业展示了法治的力量：东道国政府的红头文件，在新加坡 SIAC 国际仲裁庭面前绝不能成为撕毁合同的挡箭牌！面对政府恶意压价，中资企业切勿单方面一味妥协让步（让步往往导致项目最终资不抵债），必须果断按下 SIAC 仲裁起诉键！本案近1.5亿美元的胜诉赔偿裁决出台后，直接迫使菲律宾总统府和财政部不得不坐回谈判桌与中资企业签署友好价格补偿框架，成功捍卫了数十亿元核心海外资产！",
        "norms_meta": "PH:EO_1008_CIAC:Sec4;PH:RA_11659_PSA_2022:Sec2_4;INTL:FIDIC_2017:Cl1.15"
    },
    {
        "case_id": "REF_CASE:PCA:Case_2017_28_Chinese_Investor_v_ASEAN_State:2020",
        "court": "Permanent Court of Arbitration (海牙常设仲裁法院 PCA)",
        "senate": "Arbitral Tribunal (依据中外双边投资条约组建之国际仲裁庭)",
        "decided": "2020-06-25",
        "az": "PCA Case No. 2017-28",
        "ecli": "ECLI:PCA:2020:28",
        "doctype": "award",
        "leitsatz": "【海牙常设仲裁法院中资水电投资人诉东盟国双边投资条约BIT征收与税收歧视胜诉裁决】：在我国大型出海央企依据中国与东盟成员国双边投资保护协定（BIT）提起的国际投资仲裁中，PCA 仲裁庭作出了具有重大历史标杆意义的终局裁决：当中国投资者依据东道国政府国家能源特许权批准、全额投资数亿美元建设大型跨境河流梯级水电站后，若东道国地方省政府及税务机关由于政局变动，突击出台地方性歧视性行政规章，以‘未足额申报地方资源税’为由擅自查封电站发电机组、单方撤销特许权协议、并强令以象征性微额价格强行‘国有化移交’给本土国有电力公司的，构成条约项下最严重的非法直接征收（Direct Expropriation）与歧视性待遇；裁决东道国政府必须依据国际法公允市场价值（FMV）全额向中资企业现金赔偿1.12亿美元本息！",
        "tenor": "【海牙常设仲裁法院终局裁决主文】：一、确认海牙常设仲裁法院仲裁庭依据中华人民共和国政府与东道国政府关于鼓励和相互保护投资协定第9条，对本案享有完全管辖权；二、终审裁定东道国地方政府撤销申请人案涉大型梯级水电站特许权协议并实施资产强制接管之行为，严重违反了双边投资条约第5条关于禁止非法征收之规定，构成直接主权非法征收；三、裁决东道国政府必须于裁决送达之日起六十日内，以自由兑换货币向申请人（中资清洁能源投资集团）全额支付征收赔偿金共计112,400,000美元（依照公允市场现金流贴现模型估值计算）；四、判令东道国政府按美国公国债同期商业利率计付自征收之日起至清偿之日的复利利息；五、本案终局裁决对东道国政府具有不可撤销之完全国际法强制执行力。",
        "tatbestand": "【案件事实与各方主张陈述】：申请人某中国大型国有电力投资集团出海子公司于2011年与东道国中央政府能源矿产部正式订立《大型梯级水电站 BOT 投资特许经营协议》，由申请人投资4.8亿美元承建并特许运营两座总装机240MW的水电站，特许期为35年。项目如期全面建成蓄水并网发电，成为该国最主要的主权清洁能源骨干支撑。然而在商业运营第5年，东道国发生政党更迭，新执政当局煽动所谓‘重新评估外资对国家命脉资源控制’的民族主义情绪。该水电站所在地的省税务局突然出台地方行政条例，认定中资电站未缴纳一项此前从未听说过且仅针对外资企业征收的巨额‘地方水资源特别消耗税’，并在短短两周内连下数道处罚令，冻结了中资企业在当地银行账户，随后地方政府竟然动用当地防暴武装力量强行接管了水电站中控室，勒令中方技术人员全部撤离，并宣布‘将电站无偿收归省属国有企业’。申请人向东道国中央最高行政法院提起申诉长达两年未获受理。中资集团毅然依据中国与该国签署的双边投资条约（BIT），向海牙常设仲裁法院（PCA）提请国际投资仲裁，直接起诉东道国主权政府，主张主权征收并要求全额市场赔偿。",
        "gruende": "【裁判理由阐述与司法论证逻辑】：海牙常设仲裁法院仲裁庭经深入审理后认为：一、关于直接征收（Direct Expropriation）之构成审查。东道国地方政府动用武装力量强行驱逐外国投资者派驻的管理人员、物理切断投资人对水电站的占有使用、并将全部发电电费划转至本土国企账户，其行为已经造成了对外国投资者合法私有财产权的彻底、永久且实质性的剥夺；这属于国际法上最典型、最无可辩驳的直接征收行为。二、征收合法性四大法定要件之全面不符。依据中外 BIT 第5条，主权征收必须严格同时满足：（1）为了公共利益；（2）依法定程序；（3）非歧视性；（4）及时、充分且有效补偿。东道国政府在接管电站过程中，既未通过正当立法程序、未给予投资者任何申辩权利，更未曾支付过哪怕一分钱的补偿款，构成彻头彻尾的严重国际法不法行为（Internationally Wrongful Act）。三、估值方法之科学确立。仲裁庭完全驳回了东道国所谓按‘资产账面历史沉没成本’赔偿的无理抗辩，采纳了国际通用的‘未来现金流折现法（DCF 法）’，按照电站未来剩余30年特许期内可稳健实现的预期净售电收益，核定赔偿金为1.12亿美元。四、【出海央企实操攻防启示】：中国央企出海动用双边投资条约（BIT）赢得破亿美元主权赔偿的划时代里程碑战例！这是我国央企近十年来在海外遭遇政治主权风险时，敢于拿起国际公法武器直接‘告赢东道国主权政府’并斩获超1.1亿美元巨额现金赔偿的最经典成功战役！过去很多中资央企受传统涉外思维束缚，在海外被地方政府欺负、甚至资产被抢了，还总是想着‘托关系友好协商’，结果越拖越被动、最终资产被彻底瓜分；本案证明：中国政府与全球上百个国家签订的双边投资协定（BIT）绝不是摆设！它是我们保护出海企业海外合法资产最硬的‘主权防弹衣’！一旦东道国胆敢搞强盗式的没收查封，中资企业必须第一时间启动 PCA/ICSID 仲裁，让东道国主权政府在全世界面前承担赔偿责任，彻底捍卫国家海外资产安全！",
        "norms_meta": "TREATY:CN_ID_BIT_1992:Art4_5;TREATY:CN_VN_BIT_1992:Art3_4;TREATY:CN_MY_BIT_1988:Art3_6"
    },
    {
        "case_id": "REF_CASE:UNCITRAL:Case_2015_02_Road_Concession_Malaysia:2017",
        "court": "UNCITRAL Arbitral Tribunal (联合国国际贸易法委员会特设仲裁庭)",
        "senate": "Ad Hoc Tribunal (由三位国际公用事业仲裁专家合议)",
        "decided": "2017-05-18",
        "az": "UNCITRAL Ad Hoc Case No. 2015-02",
        "ecli": "ECLI:UNCITRAL:ARB:2017:02",
        "doctype": "award",
        "leitsatz": "【UNCITRAL仲裁庭马来西亚收费公路特许权取消过路费政府补贴违约赔偿裁决】：在依据联合国国际贸易法委员会（UNCITRAL）仲裁规则审理的重大收费公路 BOT 特许经营权纠纷中，仲裁庭确立了具有权威效力的政府主权补贴违约裁判准则：当东道国联邦政府由于民选政治考量，公开宣布取消某重大国家干线高速公路原定的过路费收费站（Toll Plaza）、并在特许经营合同补充协议中正式承诺由‘联邦财政向特许经营项目公司逐年按车辆流量全额拨付对等缺口补贴资金（Revenue Shortfall Compensation）’后，政府财政部在后续年度借口‘国家财政赤字承压’擅自削减并停止拨付补贴款的行为，构成严重的合同主权违约；裁决政府必须全额补发拖欠的数亿令吉补贴资金及商业利息！",
        "tenor": "【UNCITRAL特设仲裁庭终局裁决主文】：一、确认仲裁申请人（中资大型基础设施投资财团与马来西亚本地特许经营联合体）与被申请人（马来西亚联邦政府工程部及财政部）签署的《特许经营补充协议》合法、有效且对联邦政府具有完全强制法律效力；二、终审裁定被申请人单方削减并停止向申请人支付案涉干线高速公路取消收费后之法定财政缺口补偿款，构成严重的根本性违约行为；三、裁决马来西亚联邦政府必须于本裁决作出之日起四十五日内，向申请人全额结清拖欠的2015至2017年度财政过路费补偿款共计385,000,000令吉（约合9,000万美元），并计付年化法定逾期利息；四、本案全部仲裁开支由被申请人负担。",
        "tatbestand": "【案件事实与各方主张陈述】：申请人某中资海外交通投资实业集团与马来西亚本土持牌基础设施开发商组建合资特许经营项目公司，投资总额逾数十亿令吉承建并特许运营连接马来西亚西海岸核心工业区的某国家级双向六车道高速公路，特许期为30年。在公路运营进入第8年时，马来西亚内阁为平息周边城镇选民抗议，总理公开宣布废除该公路上两座客流最大的主线收费站，实行‘全民免费通行’。为平复投资人，马来西亚联邦政府与项目公司签署了极具约束力的《特许经营补充补偿协议》，明确锁定：废除收费站后，由马来西亚联邦政府财政部设立专项预算科目，依据第三方独立车流感应雷达数据，按月将原本应收的过路费差额‘一分不少’地全额现金补贴给项目公司。然而在执行了两年后，马来西亚政局发生激变，新内阁以‘前朝政府协议加重国家主权财政负担、且国库赤字过高’为由，单方发布财政部令宣布中止拨付补贴款，强令项目公司自行消化损失。项目公司向 UNCITRAL 特设仲裁庭提请仲裁，要求马来西亚主权政府遵约赔偿。",
        "gruende": "【裁判理由阐述与司法论证逻辑】：UNCITRAL 仲裁庭经深入审理后认为：一、主权国家缔结合同即法律（Pacta Sunt Servanda）在特许经营中的神圣性。马来西亚政府在撤销收费站时，为了换取政治公共利益，自愿签署了以国家财政承诺兜底的补充补偿协议；该协议属于具有完全民商事实体约束力的主权合同行为，绝非可以随意撤销的‘恩赐或施舍’。二、主权财政困难绝不能成为法定违约免责抗辩。依据现代国际契约法，即使国家面临宏观财政赤字压力，也不能以此作为免除合法到期金钱债务的法定不可抗力借口；国家既然享受了撤销收费站带来的公共福利，就必须对等承担兑现现金补贴之国际信用义务。三、保护外商长期投资确定性。仲裁庭完全驳回了政府提出的‘协议加重纳税人负担’的民粹政治抗辩，全额判令政府履约赔付。四、【出海央企实操攻防启示】：中资央企投资海外公用基础设施（收费公路、轨道、码头）面对‘政府取消收费’的教科书级防线！在发展中国家投资高速公路或桥梁，最常遇到的政治风险就是‘当地老百姓上街游行抗议过路费太贵，政府为了平息民愤一纸公文把收费站强行砸了或者取消’！中资出海企业在面对政府提出‘取消收费、改由财政补贴’时，必须建立最高级别的法律防火墙：（1）坚决要求在补充协议中白纸黑字写死‘车流量以独立第三方电子感应为准，政府负有绝对无条件先期刚性全额划款义务’；（2）管辖条款坚决写死‘在海牙或新加坡由 UNCITRAL/SIAC 仲裁解决’；（3）一旦政府敢以财政没钱为由赖账，立即启动国际仲裁，让政府在国际信用评级被降级的威慑下，老老实实全额吐出补贴款！",
        "norms_meta": "TREATY:CN_MY_BIT_1988:Art3_6;MY:Contracts_Act_1950:Sec52_55;INTL:FIDIC_2017:Cl17_1"
    },
    {
        "case_id": "REF_CASE:ICC:Case_18450_URDG_758_Demand_Guarantee:2015",
        "court": "International Court of Arbitration of the ICC (国际商会国际仲裁院)",
        "senate": "Arbitral Tribunal (由三位国际银行与贸易金融仲裁员合议)",
        "decided": "2015-06-22",
        "az": "ICC Case No. 18450/TO",
        "ecli": "ECLI:ICC:ARB:2015:18450",
        "doctype": "award",
        "leitsatz": "【国际商会ICC仲裁院URDG 758保函违约陈述必备要件与担保行合法拒付里程碑裁决】：在涉及中资银行海外分行作为转开行（Confirming/Issuing Bank）开具的涉外见索即付独立保函纠纷中，ICC 仲裁庭作出了具有全球银行保函判例法权威效力的终局裁决：依据国际商会《见索即付保函统一规则》（URDG 758）第15条第1款明文规定，受益人提出索偿时，除提交保函载明的付款请求书外，必须在单据中明确陈述‘申请人在基础合同履约中究竟在何种特定方面存在违约（Statement of Breach）’；若受益人提交的索赔函仅使用极简的笼统词句（如‘总承包商已发生违约、请立即付款’），而欠缺对违约事实与违约条款的具体陈述，构成单据表面重大不符（Discrepant Demand）；担保行依据第20条在5个营业日内发出拒付通知合法有效，裁决全额驳回受益人要求强制兑付保函的诉求！",
        "tenor": "【ICC国际仲裁庭终局裁决主文】：一、终审确认仲裁申请人（海外工程发包人某跨国置业集团）向担保行提交的案涉第PB-2013-09号履约保函项下付款索偿单据，由于未能满足 URDG 758 第15条第1款关于载明具体违约事实陈述之强制法定要件，构成表面单据重大不符；二、终审裁定被申请人（某中资大型国有银行新加坡分行）在严格5个银行营业日内签发列明不符点的《正式拒付通知书（Notice of Rejection）》，完全符合 URDG 758 第20条之规程，拒付行为完全合法正当；三、全额驳回申请人要求判令中资银行无条件兑付18,500,000美元保函款项及逾期利息的全部仲裁请求；四、确认申请人向中资银行出具的索赔单据由于瑕疵自始失效，保函金额不予扣划；五、本案仲裁费用由申请人全额负担。",
        "tatbestand": "【案件事实与各方主张陈述】：申请人（东盟某大型石化仓储开发商）作为发包人，与某中资装备工程总承包商签订大型储罐及油品码头 EPC 合同。被申请人某中资大型国有银行新加坡分行作为担保行，受总承包商委托向申请人开具了金额为1,850万美元的见索即付不可撤销履约保函，保函正文明确载明受国际商会 URDG 758 惯例拘束。在工程安装接近尾声时，申请人与总承包商因几项阀门采购单价及工程试运行节点发生激烈争执。申请人决定动用‘核威慑’手段，直接向中资银行新加坡分行营业部柜台正式递交了《保函付款索赔书》，该索赔函文字极简，仅写明：‘我司作为受益人，特此声明总承包商未能按合同履行其义务，请贵行根据保函立即将全额1,850万美元电汇至我司指定渣打银行账户’。中资银行合规部门在收到索赔单据后，严格启动 URDG 758 审单机制，在第4个营业日正式向申请人发出 SWIFT 拒付电报，明确指出：根据 URDG 758 第15条第1款，索赔函中必须明确说明承包商‘在何种具体方面（In what respect）’违反了主合同义务，而申请人仅泛泛声称‘未能履约’，欠缺必备的法定违约陈述，构成致命单据不符，银行依法拒绝付款！申请人愤怒向 ICC 提请仲裁，声称保函是见索即付，只要受益人说了违约银行就必须掏钱，银行无权挑刺文字程序。中资银行坚决应诉维权。",
        "gruende": "【裁判理由阐述与司法论证逻辑】：ICC 国际仲裁庭经深入审查国际保函规则后一致认为：一、URDG 758 第15条违约陈述条款的重大革新价值。在早期的 URDG 458 或旧式简单见索即付保函中，受益人往往只需一纸‘请打款’即可瞬间将承包商巨资划走，导致保函被恶意滥用的险情极其严重；国际商会在制定全新 URDG 758 时，深思熟虑地确立了第15条第1款这一‘强制门槛’——受益人必须明确指出承包商是在工期、质量、还是其他具体哪个条款上违约。该规定旨在强制受益人审慎行权，并防止无事实根据的突袭索兑。二、单据严格相符原则（Strict Compliance）在保函领域的铁律地位。独立保函的生命线是‘银行只看单据表面、不管基础合同实质’；既然是单据交易，受益人提交的文件就必须一字不差地严格符合规则所要求的全部要素；欠缺法定必备要素的陈述，在国际保函法理上直接等同于‘未提交有效的索赔’。三、中资银行规范审单值得高度保护。被申请人严格遵守了5个营业日的审单时效，并一次性详尽列明了全部不符点，拒付程序完美无瑕，依法免于承担任何赔偿责任。四、【出海央企实操攻防启示】：中资央企出海在保函被索兑生死关头‘让银行专业拒付’的终极自救秘笈！这是每一位出海总包财务总监和法务经理必须烂熟于心的‘神级风控战术’！中资出海企业每年对外开立上百亿美元的履约和预付款保函，一旦遭遇海外业主恶意索兑，很多企业慌忙去打官司往往来不及。此时，最有效、最神速的第一道防线是在银行柜台！出海企业在开立保函时，必须强制要求保函管辖规则适用 URDG 758！一旦业主来索兑，立即联合开证行（尤其是中资银行海外分行）启动 URDG 758 第15条放大镜式穿透审单！东盟很多不专业的私营业主或外聘法务，写索赔函时常常偷懒只写一句‘总包违约了快给钱’；只要他们漏写了具体的违约条款和具体违约事实，银行就可以名正言顺依据本案判决，在5天内直接把业主的索赔单据依法作废退件！直接在柜台把业主的恶意索兑彻底干翻！",
        "norms_meta": "INTL:URDG_758:Art15;INTL:URDG_758:Art20;INTL:URDG_758:Art33"
    },
    {
        "case_id": "REF_CASE:ICC:Case_24110_CISG_Turbine_Delivery:2021",
        "court": "International Court of Arbitration of the ICC (国际商会国际仲裁院)",
        "senate": "Arbitral Tribunal (由三位国际货物买卖公约法仲裁员合议)",
        "decided": "2021-07-28",
        "az": "ICC Case No. 24110/MK",
        "ecli": "ECLI:ICC:ARB:2021:24110",
        "doctype": "award",
        "leitsatz": "【国际商会ICC仲裁院CISG公约第79条客观履行障碍与跨国海运封锁免责裁判先例】：在涉东盟大型电站核心重型燃气轮机跨国跨境采购合同纠纷中，ICC 仲裁庭确立了有关《联合国国际货物销售合同公约》（CISG）第79条履行障碍免责的权威裁判准则：当跨国货物买卖合同准据法适用 CISG 时，卖方（某中国重型装备制造集团）因全球重大突发航运航道物理封锁及跨国口岸全面军事戒严导致重型燃机设备迟延交付达5个月，若该客观履行障碍（Impediment）完全超出了卖方合理控制范畴（Beyond Control）、缔约时不可合理预见、且卖方在商业上已穷尽一切合理努力寻找替代滚装船航线未果时，卖方依法免除赔偿由此给买方（东南亚电站总包商）造成的任何误期延误违约金责任；买方强行单方扣罚上千万美元违约金构成违法，裁决全额退还设备尾款！",
        "tenor": "【ICC国际仲裁庭终局裁决主文】：一、终审确认仲裁申请人（中国某大型重型燃气轮机装备制造央企）在案涉向被申请人（东南亚某联合循环电站EPC总承包商）交付两台F级重型燃气轮机及配套发电机组过程中，发生的连续152天交货迟延，依法完全满足 CISG 公约第79条第1款项下客观履行障碍法定免责要件；二、裁定申请人法定免于承担因迟延交货给被申请人造成的一切误期损害赔偿金（Liquidated Damages）或违约赔偿责任；三、终局判定被申请人此前单方从申请人设备结算款中强行扣收的14,200,000美元违约金缺乏法律依据，属于非法扣款；四、判决被申请人必须于三十日内，向申请人全额结清拖欠的设备采购尾款及质保金共计14,200,000美元，并计付自违约之日起按法定利率计算之商业利息；五、本案仲裁费用由被申请人全额负担。",
        "tatbestand": "【案件事实与各方主张陈述】：申请人中国某顶尖动力装备制造央企与被申请人（某跨国工程集团在新加坡设立的区域总包子公司）签署总价款为1.15亿美元的《两套F级重型燃气轮机发电机组跨国买卖合同》，用于东道国某主权级大型燃气联合循环电站项目。合同约定适用国际贸易术语 CIF 交付，合同准据法适用《联合国国际货物销售合同公约》（CISG）。在设备总装完成装船海运途中，恰逢苏伊士运河突发超大型集装箱货轮搁浅导致双向航道发生历史性严重瘫痪封锁长达数周；加之红海及中东多国爆发区域武装冲突实施强制性军事封海，全球特种超重件大件滚装海运运力全面断裂。申请人设备运输船被迫绕行非洲好望角，并在中转港口遭遇连续数月的军事管制与检疫扣押，导致设备最终运抵东道国项目现场港口的时间较合同原定交货期整整滞后了152天。申请人按照 CISG 第79条第4款，在障碍发生之日起48小时内连续向买方发出书面不可抗力与履行障碍正式通告并提供了中国贸促会（CCPIT）出具的公证书。然而被申请人在收到合格设备并安装投产后，竟直接在最后一笔设备信用证结算中，强行按每日合同额0.1%全额扣罚了整整1,420万美元的延误交货罚款。中资企业向 ICC 提起国际仲裁维权。",
        "gruende": "【裁判理由阐述与司法论证逻辑】：ICC 国际仲裁庭经深入审理后认为：一、CISG 第79条第1款免责的三大严格法定构成要件。（1）客观障碍超出当事人控制范畴（Beyond his control）；（2）缔约时无法合理期望其考虑到该障碍（Could not reasonably be expected to take into account）；（3）无法合理期望其避免或克服该障碍或其后果。二、案涉海运极端事件的法律定性。全球核心咽喉航道突发物理性严重瘫痪与国际公海军事封锁，属于全球百年罕见的极端外部公权力及客观灾难事件，任何处于商业地位的机电制造卖方在缔约时均无法合理预见该等全球物流链的整体性休克；在案海事追踪日志证实，中资企业在运河受阻后已第一时间不惜额外增加数百万美元燃油成本指令货轮绕行好望角，并已穷尽一切国际商业合理努力（All reasonable steps taken）去克服障碍，因此完全满足公约第79条客观免责标准。三、及时通报义务的无瑕疵履行。申请人在48小时内出具了详尽通告及官方商会公证书，严格遵守了公约第79条第4款的合理通知义务，买方早已掌握全部客观情势，不存在任何信息不对称。四、【出海央企实操攻防启示】：中资高端装备制造出海遭遇跨国海运供应链暴雷的‘CISG第79条标准免责打法’！中国的高铁列车、风力发电机、重型燃机、变压器等重型高端装备出海规模巨大，跨国海运往往面临红海危机、苏伊士运河堵塞、地缘冲突禁运等极其复杂的全球供应链断裂风险。一旦交货延期，海外买方动辄索赔上千万美元延误罚款！本案给出了中资装备出海最完美的法律防御模板：（1）在跨国买卖合同中，绝不能适用买方属地国法律，坚决锁定适用联合国《国际货物销售合同公约》（CISG）；（2）一旦发生海运或清关客观受阻，严密启动 CISG 第79条程序——48小时内发出正式通知并附带中国国际贸易促进委员会（CCPIT）出具的《不可抗力事实性证明书》；（3）详细记录企业为了止损所尝试的绕航、空运替代等努力过程；只要把这套标准化证据链做扎实，在国际仲裁庭上就能100%免除全部违约金责任，安全拿回全部数亿元设备款！",
        "norms_meta": "INTL:CISG:Art79;INTL:CISG:Art25;INTL:CISG:Art74_77"
    },
    {
        "case_id": "REF_CASE:ICSID:ARB_15_40_SGS_v_Philippines:2018",
        "court": "International Centre for Settlement of Investment Disputes (世界银行 ICSID 仲裁庭)",
        "senate": "Arbitral Tribunal (由三位国际公法投资争端权威仲裁员合议)",
        "decided": "2018-02-12",
        "az": "ICSID Case No. ARB/15/40",
        "ecli": "ECLI:ICSID:ARB:2018:15:40",
        "doctype": "award",
        "leitsatz": "【世界银行ICSID投资仲裁伞形条款Umbrella Clause与主权借款税收代扣纠纷终局裁决先例】：在外国投资者诉主权国家特许服务与税收代扣国际投资争端中，ICSID 仲裁庭确立了有关双边投资协定（BIT）中‘伞形保护条款（Umbrella Clause）’的重大适用法理：依据瑞士-菲律宾 BIT 第10条第2款之规定，东道国庄严承诺‘应恪守其对另一方投资者的投资所承担的任何其他特定契约义务（Observe any obligation it may have entered into）’；当东道国政府机关在依据长期国家服务合同履行支付检验监管服务对价时，若财政部与国家税务局违反合同关于‘净额免税支付（Gross-Up / Tax Free）’的明文承诺，强行动用国内法税收强制代扣高达数十亿比索预扣税并借故扣压应付款项时，该违约行为依据伞形条款直接被‘实质性升格（Elevated）’为国际条约层面的主权违约，裁决东道国主权政府承担全额履约返还责任！",
        "tenor": "【ICSID仲裁庭终局裁决主文】：一、终审确认仲裁庭依据瑞士-菲律宾双边投资协定第10条第2款之伞形条款，对案涉进出口货物全面国际海关检验服务合同项下的全部金钱违约争议享有完全的条约管辖权；二、终审裁定菲律宾共和国财政部及海关总署单方扣留应付服务费、并强制征收未经合同约定的高额内部预扣税款之行政行为，严重违反了条约项下恪守投资承诺之主权义务；三、裁决菲律宾共和国主权政府必须于裁决作出之日起六十日内，向申请人（SGS 国际检验认证集团）全额支付拖欠的服务对价本金共计142,000,000美元（约合逾70亿菲律宾比索）；四、判令菲律宾政府按照伦敦银行同业拆借利率（LIBOR）加计商业复利违约利息；五、本案仲裁费用由菲律宾政府承担70%。",
        "tatbestand": "【案件事实与各方主张陈述】：申请人瑞士通用公证行（SGS Société Générale de Surveillance S.A.）系全球公认的特种海关商品检验与国际质量认证跨国巨头。1992年，SGS 与菲律宾共和国主权政府签署了著名的《全面进出口货物装船前独立海关检验特许服务协议（CISS）》，受菲律宾国家授权，负责在全球各大主要口岸对所有海运发往菲律宾的进口大宗商品实施强制性报关价格核验与质量把关，以协助菲律宾打击跨国走私与海关偷逃关税。协议明确约定：菲律宾政府按检验货物到岸总货值的固定百分比按月向 SGS 支付专业服务费，且合同专属条款明文约定该费用为‘绝对净额支付，菲律宾政府无权扣除任何菲律宾国内预扣所得税’。SGS 建立起庞大的在岸分析实验室并高质履约多年，为菲律宾国库挽回了数百亿比索关税损失。然而随着菲律宾政权轮替，新政府为弥补巨额财政赤字，国家国内税务局（BIR）与财政部突然单方违约，声称根据菲律宾国内税法典，向非居民外企付款必须强制扣除高达20%~30%的预扣税，并以此为由无限期扣压拖欠 SGS 经核定的大额服务账单累计逾1.4亿美元达数年之久。SGS 依据瑞士-菲律宾 BIT 向世行 ICSID 提请国际投资仲裁，控诉菲律宾政府违反条约伞形条款并构成事实征收。",
        "gruende": "【裁判理由阐述与司法论证逻辑】：ICSID 仲裁庭经深入审理后认为：一、关于 BIT 伞形条款（Umbrella Clause）的赋能机制与法理渊源。双边投资条约第10条第2款系主权国家之间订立的庄严国际法承诺，其核心功能正是为了‘给东道国与外国投资者之间订立的特定具体商业契约义务撑起一把国际法的保护伞’；只要合同义务明确、具体且有效，东道国主权机关违背该合同承诺的行为，依法直接被伞形条款转化为对国际双边投资条约本身的直接违约。二、税收主权不能作为违背明确契约担保的挡箭牌。主权国家虽然依法享有国内税收管辖权，但在涉外重大招商引资特许协议中，主权国家完全享有通过明示‘税收净额承担条款（Tax Indemnity / Gross-up Clause）’向外国投资人作出税收优惠担保的意思自治民事权利能力；菲律宾政府在合同中既然已明确承诺‘净额免税支付’，事后就绝对不得借由国内税务局的一纸行政法规强行单方推翻契约，这违背了国际法上最根本的禁止反言与善意原则。三、保护国际营商环境法治信用。全额支持原告追讨全部服务款项。四、【出海央企实操攻防启示】：中资央企出海在东盟签署政府重大特许权合同锁定‘伞形保护’的顶级实操指南！这是涉外投资法中最顶层的‘以条约锁合同’的高阶战法！中资企业在东盟投资大型基础设施、公用事业或特许服务（如水质检测、环保监测、港口引航），很多时候合同是跟东道国部委签的，当地税务局或地方政府最喜欢秋后算账——突然翻脸按国内法下达‘税收追缴单’，强行把原本承诺的利润通过预扣税或增值税直接扣掉30%！本案给中资企业提供了最强的反击思路：在投资前，必须确保母公司所在国与东道国之间的 BIT 包含‘伞形条款（Umbrella Clause）’；在主合同中，坚决锁定‘税收总额提升净额条款（Gross-up Clause）’！一旦当地税局违约乱扣税，中资企业直接依据 BIT 伞形条款向 ICSID 提告，将普通的‘税务违约纠纷’瞬间升格为‘主权国际违约’，一举逼迫东道国财政部老老实实全额退还扣税款！",
        "norms_meta": "TREATY:CN_PH_BIT_1992:Art3_5;PH:BIR_Revenue_Regulation_11_2018:Sec2_57;TREATY:RCEP:Chapter10_Services"
    }
]

